import 'api_client.dart'; import 'models.dart';
class AuthRepository { AuthRepository(this.api); final ApiClient api; Future<void> password(String email, String password) async => api.request('/api/auth/login', method: 'POST', body: {'email': email, 'password': password}); Future<void> mfa(String code) async => api.request('/api/auth/mfa', method: 'POST', body: {'code': code}); }
class HouseholdRepository { HouseholdRepository(this.api); final ApiClient api; Future<HouseholdDashboard> dashboard() async => HouseholdDashboard.fromJson(await api.request('/api/v1/dashboard')); Future<NotificationPage> notifications({int offset = 0}) async => NotificationPage.fromJson(await api.request('/api/v1/notifications?limit=20&offset=$offset')); Future<void> registerDevice(String platform, String token) async => api.request('/api/v1/devices', method: 'POST', body: {'platform': platform, 'token': token}); }
enum QueueState { pending, conflict, sent }
class PendingMutation { PendingMutation(this.idempotencyKey, this.path, this.body, {this.state = QueueState.pending}); final String idempotencyKey; final String path; final Map<String, dynamic> body; QueueState state; }
class OfflineMutationQueue { final List<PendingMutation> items = []; void enqueue(PendingMutation mutation) => items.add(mutation); Future<void> flush(ApiClient api) async { for (final item in items.where((item) => item.state == QueueState.pending)) { try { await api.request(item.path, method: 'POST', body: {...item.body, 'idempotencyKey': item.idempotencyKey}); item.state = QueueState.sent; } on ApiException catch (error) { if (error.statusCode == 409) item.state = QueueState.conflict; else rethrow; } } } }
